// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Üçgenlerde açı, kenar-açı bağıntıları, eşlik-benzerlik ve üçgenin yardımcı elemanları-merkezleri (ağırlık, iç-dış teğet, diklik, çevrel merkez) (kolay).
const ozMathematics15Kolay = <(String, String, List<String>, String)>[
  ('Düzlemde çizilen herhangi bir dışbükey üçgenin her köşesinden birer dış açı alınıp toplandığında ulaşılan sabit açı ölçüsü kaçtır?', '360 derece', ['180 derece', '270 derece', '540 derece'], 'Tüm dışbükey çokgenlerde her köşeden alınan birer dış açının ölçüleri toplamı kenar sayısından bağımsız olarak 360 derecedir.'),
  ('İç açılarının ölçüleri 3, 5 ve 7 sayılarıyla doğru orantılı olan bir üçgenin en küçük dış açısının ölçüsü ne kadardır?', '96 derece', ['84 derece', '108 derece', '132 derece'], 'İç açılar 3k + 5k + 7k = 180 eşitliğinden k = 12 bulunur; en büyük iç açı 84 derece olduğundan buna komşu en küçük dış açı 180 - 84 = 96 derecedir.'),
  ('Tepe açısının ölçüsü 38 derece olan ikizkenar üçgen biçimindeki bir flamanın eş taban açılarından her biri kaç derecedir?', '71 derece', ['69 derece', '72 derece', '76 derece'], 'İkizkenar üçgende taban açıları birbirine eşittir; (180 - 38) / 2 = 142 / 2 = 71 derece elde edilir.'),
  ('Açı ölçüleri radyan cinsinden π/6, π/3 ve π/2 olan bir üçgenin açılarına ve kenarlarına göre sınıflandırması aşağıdakilerden hangisidir?', 'Dik açılı çeşitkenar üçgen', ['Dar açılı çeşitkenar üçgen', 'Geniş açılı ikizkenar üçgen', 'Dik açılı ikizkenar üçgen'], 'Radyan değerleri dereceye çevrildiğinde 30°, 60° ve 90° elde edilir; bir açısı 90° ve tüm açıları farklı olduğundan dik açılı çeşitkenar üçgendir.'),
  ('İçbükey (konkav) bir ABCD dörtgeninde C köşesi içe bükülmüş durumdadır. m(BAD) = 42°, m(ABC) = 33° ve m(ADC) = 29° verildiğine göre dörtgenin dış bölgesinde kalan m(BCD) açısı kaç derecedir?', '104°', ['94°', '106°', '114°'], 'Bumerang özelliğine göre içe bükük köşenin dış taraftaki açısı diğer üç iç açının toplamına eşittir: 42° + 33° + 29° = 104°.'),
  ('m(A) = 90° olan bir ABC dik üçgeninde hipotenüse ait kenarortay [AD] çiziliyor. m(ADC) = 118° olduğuna göre C köşesindeki dar açı kaç derecedir?', '31°', ['29°', '34°', '59°'], 'Dik üçgende muhteşem üçlü özelliğinden |AD| = |BD| = |DC| olur. İkizkenar ADC üçgeninde tepe açısı 118° olduğundan taban açısı m(C) = (180° - 118°) / 2 = 31° bulunur.'),
  ('Düzgün altıgen biçimindeki bir masa örtüsünün ardışık üç köşesini birleştiren üçgen parçasının eş olan dar açılarından birinin ölçüsü kaçtır?', '30 derece', ['20 derece', '24 derece', '36 derece'], 'Düzgün altıgenin bir iç açısı 120 derecedir ve kenarları eşittir. Oluşan ikizkenar üçgenin tepe açısı 120° olduğundan dar taban açıları (180 - 120) / 2 = 30 derecedir.'),
  ('Paralel iki cadde arasında zikzak çizen bir yürüyüş yolunun birinci caddeyle yaptığı dar açı 47°, ikinci caddeyle yaptığı dar açı 38° ise iki yürüyüş kolunun kesiştiği köşedeki dar kırılma açısı kaç derecedir?', '85°', ['75°', '89°', '95°'], 'Paralel doğrular arasındaki M kuralına göre kırılma köşesindeki açı, kolların paralel caddelerle yaptığı ters yönlü dar açıların toplamı olan 47° + 38° = 85° değerine eşittir.'),
  ('Akrep ve yelkovan kollarının eşit uzunlukta tasarlandığı dekoratif bir saat tam 05.00\'i gösterdiğinde, kolların uçlarını birleştiren doğru parçasının yelkovanla yaptığı dar açı kaç derecedir?', '15 derece', ['12 derece', '18 derece', '20 derece'], 'Saat 05.00\'te akrep ile yelkovan arasındaki açı 5 · 30° = 150° olur. Kollar eşit uzunlukta olduğundan taban açısı (180° - 150°) / 2 = 15 derecedir.'),
  ('Üçgen biçimindeki bir cam vitrayda A açısı B açısının 2 katından 4° fazla, C açısı ise B açısının 3 katından 10° eksiktir. Vitrayın en geniş köşesindeki iç açı kaç derecedir?', '83°', ['76°', '79°', '87°'], 'm(B) = x denirse (2x + 4) + x + (3x - 10) = 180 denkleminden 6x = 186 ve x = 31° bulunur. Köşe açıları 66°, 31° ve 83° olduğundan en büyük iç açı 83° olur.'),
  ('Eşkenar bir ABC üçgeninde [BC] kenarının C yönündeki uzantısı üzerinde |CD| = |AC| olacak şekilde bir D noktası alınıyor. A ve D noktaları birleştirildiğinde oluşan m(BAD) açısı kaç derecedir?', '90 derece', ['75 derece', '80 derece', '105 derece'], 'ABC eşkenar olduğundan m(ACB) = 60° ve bütünleri m(ACD) = 120° olur. |AC| = |CD| olduğundan ACD ikizkenar üçgeninde m(CAD) = 30° bulunur; dolayısıyla m(BAD) = 60° + 30° = 90 derecedir.'),
  ('İkizkenar bir üçgende tepe açısından tabana indirilen dikme aynı zamanda aşağıdaki yardımcı elemanlardan hangilerinin görevini üstlenir?', 'Hem açıortay hem kenarortay', ['Yalnızca kenar orta dikme', 'Hem dış açıortay hem yükseklik', 'Yalnızca çevrel çember çapı'], 'İkizkenar üçgende simetri ekseni özelliği gereği tepe açısından tabana inen yükseklik aynı zamanda iç açıortay ve kenarortaydır.'),
  ('Bir üçgende bir köşeden karşı kenara çizilen doğru parçası hem iç açıortay hem de yükseklik görevi görüyorsa bu üçgen hakkında kesin olarak ne söylenebilir?', 'O köşeyi birleştiren iki kenarı birbirine eşittir', ['Üç kenar uzunluğu da birbirine eşittir', 'Karşı kenarın uzunluğu yan kenarların yarısıdır', 'Tepe açısının ölçüsü daima doksan derecedir'], 'Bir üçgende açıortay ile yüksekliğin çakışması (YA -> YAKİ kuralı), çizildiği köşedeki iki yan kenarın eşit olduğunu yani ikizkenarlığı kesin kılar.'),
  ('Köşeleri P, R ve S olan bir üçgende P açısının bütünleri 115°, R açısının tümleri 28° olarak veriliyor. Buna göre S köşesindeki dış açının ölçüsü kaç derecedir?', '127°', ['117°', '123°', '133°'], 'P açısının bütünleri dış açısı olduğundan P dış açısı 115° (iç açısı 65°), R açısının tümleri 28° olduğundan m(R) = 62° bulunur. S dış açısı komşu olmayan iki iç açının toplamıdır: 65° + 62° = 127°.'),
  ('Eş iki adet ikizkenar dik üçgen cetvel, dik köşeleri çakışacak ve aralarında boşluk kalmayacak biçimde düz bir zemine yerleştiriliyor; ancak biri diğerinin üzerine 26 derecelik açıyla kısmen biniyor. Cetvellerin dışta kalan iki dik kenarı arasındaki geniş açı kaç derecedir?', '154°', ['144°', '152°', '164°'], 'İki dik açının toplamı normalde 90° + 90° = 180° iken 26° üst üste binme gerçekleştiğinden dış kenarlar arasındaki açı 180° - 26° = 154° olur.'),
  ('Karton bir eşkenar üçgen, simetri eksenlerinden biri boyunca ikiye katlandığında üst üste gelen dik üçgen biçimindeki parçanın dar açılarının farkı kaç derecedir?', '30 derece', ['15 derece', '20 derece', '45 derece'], 'Eşkenar üçgen simetri ekseni boyunca katlandığında 30°-60°-90° dik üçgeni oluşur; dar açıların farkı 60° - 30° = 30 derecedir.'),
  ('Üçgen şeklindeki düz bir kağıdın üç köşesi, taban üzerindeki tek bir noktada boşluk kalmadan ve üst üste binmeden birleştirilerek katlanıyor. Bu etkinlik temel olarak hangi geometrik gerçeği görselleştirmek için kullanılır?', 'İç açılar toplamının 180 derece olduğunu', ['Dış açılar toplamının 360 derece olduğunu', 'Kenarortayların tek noktada kesiştiğini', 'En uzun kenarın büyük açıyı gördüğünü'], 'Üç köşe açısı taban doğrusu üzerindeki bir noktada yan yana geldiğinde doğru açı (180°) oluşturur; bu da üçgenin iç açıları toplamını somut olarak gösterir.'),
  ('Eş iki ikizkenar üçgen biçimindeki flamanın tepe açıları 32\'şer derecedir. Bu iki flama tepe noktaları çakışacak ve birer yan kenarları tam örtüşecek biçimde yan yana dizildiğinde en dışta kalan iki yan kenar arasındaki açı kaçtır?', '64 derece', ['58 derece', '68 derece', '74 derece'], 'Ortak kenar boyunca yan yana konulan eş iki tepe açısının toplamı 32° + 32° = 64 derece olur.'),
  ('Bir KLM üçgeninde [KL] = [KM] olup [LM] tabanına paralel çizilen bir doğru [KL] kenarını D, [KM] kenarını E noktasında kesiyor. m(LDE) = 119° olduğuna göre K tepe açısının ölçüsü kaç derecedir?', '58°', ['52°', '61°', '62°'], '[DE] // [LM] olduğundan karşı durumlu açılardan m(L) = 180° - 119° = 61° bulunur. İkizkenar üçgende m(M) = 61° olup m(K) = 180° - 122° = 58° elde edilir.'),
  ('Bir ABC üçgeninin iç bölgesinde alınan K noktası için [BK] ve [CK] doğru parçaları çiziliyor. m(BAC) = 48°, m(ABK) = 19° ve m(ACK) = 27° olduğuna göre m(BKC) geniş açısının ölçüsü kaçtır?', '94°', ['86°', '92°', '96°'], 'ABKC içbükey dörtgeninde bumerang kuralı gereğince m(BKC) = m(BAC) + m(ABK) + m(ACK) = 48° + 19° + 27° = 94° bulunur.'),
  ('Köşeleri D, E ve F olan bir üçgende D açısının ölçüsü 70° olup E ve F köşelerine ait iç açıortaylar I noktasında kesişmektedir. Buna göre m(EIF) geniş açısı kaç derecedir?', '125°', ['115°', '120°', '135°'], 'İki iç açıortayın kesişim açısı m(EIF) = 90° + m(D)/2 = 90° + 70°/2 = 125° formülüyle elde edilir.'),
  ('Çeşitkenar bir üçgenin iç açılarından biri radyan cinsinden 5π/12, diğeri ise π/4 olarak ölçülüyor. Üçüncü iç açının derece cinsinden değeri aşağıdakilerden hangisidir?', '60°', ['45°', '55°', '75°'], '5π/12 = 75° ve π/4 = 45° olduğundan üçüncü iç açı 180° - (75° + 45°) = 60° bulunur.'),
  ('Bir ikizkenar üçgenin tepe açısı 2α artarsa eş olan taban açılarından her birinin ölçüsünde nasıl bir değişim gözlenir?', 'α kadar küçülür', ['2α kadar küçülür', 'α/2 kadar küçülür', 'α kadar büyür'], 'Taban açısı (180° - T)/2 olduğundan tepe açısı T yerine T + 2α geldiğinde yeni taban açısı (180° - T)/2 - α olur; yani α kadar küçülür.'),
  ('Düz bir zemine dik duran bir duvar ile zemin arasına yerleştirilen doğrusal bir kalas, zeminle 53° açı yapmaktadır. Kalasın alt ucu zeminde kaydırılarak zeminle yaptığı açı 37° değerine düşürüldüğünde kalasın üst ucunun duvarla yaptığı dar açı kaç derece artar?', '16 derece', ['14 derece', '18 derece', '26 derece'], 'Dik üçgende dar açılar tümlerdir. İlk durumda duvarla yapılan açı 90° - 53° = 37°, ikinci durumda 90° - 37° = 53° olur; artış 53° - 37° = 16 derecedir.'),
  ('|AB| = |AC| olan ikizkenar ABC üçgeninin [AB] ve [AC] eş kenarları üzerine üçgenin dış bölgesine doğru sırasıyla eşkenar ABD ve eşkenar ACE üçgenleri çiziliyor. m(BAC) = 44° ise m(DAE) geniş açısı kaç derecedir?', '164°', ['156°', '160°', '168°'], 'A köşesi etrafında yan yana gelen üç açının toplamı m(DAB) + m(BAC) + m(CAE) = 60° + 44° + 60° = 164° olur.'),
  ('Herhangi bir dışbükey üçgenin dış açılarından en az kaç tanesi geniş açı olmak zorundadır?', 'En az iki tanesi', ['Yalnızca bir tanesi', 'Her zaman üç tanesi', 'Hiçbiri geniş olmak zorunda değildir'], 'Üçgenin en az iki iç açısı dar açı (<90°) olduğundan bunların bütünleri olan en az iki dış açı kesinlikle geniş açıdır (>90°).'),
  ('Simetrik ikizkenar üçgen biçimindeki bir çatı makasında her iki yan kolun yatay tavan kirişiyle yaptığı eğim açısı 23 derecedir. Çatının en üst birleşim noktasındaki mahya (tepe) açısı kaç derecedir?', '134°', ['124°', '132°', '144°'], 'İkizkenar üçgende taban açıları 23\'er derece olduğundan tepe açısı 180° - (23° + 23°) = 134° olarak hesaplanır.'),
  ('Tabanı ortak olacak biçimde bir eşkenar üçgenin iç bölgesine ikizkenar dik üçgen çiziliyor. Aynı taban köşesinden çıkan iki yan kenar arasında kalan dar açının ölçüsü kaç derecedir?', '15°', ['10°', '20°', '25°'], 'Eşkenar üçgenin taban açısı 60°, ikizkenar dik üçgenin taban açısı ise 45° olduğundan aralarındaki fark 60° - 45° = 15° bulunur.'),
  ('TUV çeşitkenar üçgeninde T köşesinin iç açısı U köşesinin iç açısından 32° fazladır. V köşesinin iç açısı 54° olduğuna göre T açısının ölçüsü kaç derecedir?', '79°', ['73°', '77°', '81°'], 'm(T) + m(U) = 180° - 54° = 126° ve m(T) - m(U) = 32° denklemleri taraf tarafa toplandığında 2·m(T) = 158° ve m(T) = 79° elde edilir.'),
  ('Bir üçgende iki iç açının ölçüleri aritmetik ortalaması 63 derecedir. Buna göre üçgenin üçüncü iç açısının ölçüsü kaç derecedir?', '54 derece', ['57 derece', '63 derece', '66 derece'], 'Aritmetik ortalaması 63° olan iki açının toplamı 2 · 63° = 126° eder; üçüncü iç açı 180° - 126° = 54 derecedir.'),
  ('İkizkenar dik üçgen biçimindeki bir kağıt, hipotenüse paralel orta tabanı boyunca katlandığında dik köşe hipotenüsün orta noktası üzerine düşüyor. Oluşan yamuğun tabanındaki dar açılardan birinin ölçüsü kaçtır?', '45 derece', ['30 derece', '60 derece', '75 derece'], 'İkizkenar dik üçgenin hipotenüs tabanındaki dar açıları 45\'er derecedir; orta taban boyunca yapılan katlama alt taban köşelerindeki 45 derecelik açıları değiştirmez.'),
  ('Bir üçgenin iki köşesindeki dış açıların ölçüleri toplamı 253 derece olduğuna göre üçüncü köşedeki iç açının ölçüsü kaç derecedir?', '73°', ['63°', '67°', '77°'], 'Dış açılar toplamı 360° olduğundan üçüncü dış açı 360° - 253° = 107° olur; buna komşu olan iç açı 180° - 107° = 73° bulunur.'),
  ('Güneş ışınlarının düz zeminle 41 derecelik açı yaptığı bir saatte, zemine dik dikilmiş bayrak direğinin tepesinden gölgesinin uç noktasına çekilen gergin ipin direkle yaptığı dar açı kaç derecedir?', '49°', ['39°', '41°', '51°'], 'Direk zemine dik olduğundan oluşan dik üçgende dar açılar tümlerdir; ipin direkle yaptığı açı 90° - 41° = 49° bulunur.'),
  ('Geniş açılı bir üçgende geniş olmayan diğer iki iç açının ölçüleri toplamı için aşağıdaki aralıklardan hangisi daima doğrudur?', '0° ile 90° arasındadır', ['45° ile 90° arasındadır', '90° ile 180° arasındadır', '60° ile 120° arasındadır'], 'Geniş açı 90° ile 180° arasında yer aldığından 180 dereceden çıkarıldığında kalan iki dar açının toplamı daima 0° ile 90° açık aralığında bulunur.'),
  ('Düzlemde ikişerli kesişen ve aynı noktadan geçmeyen üç doğrunun oluşturduğu üçgenin köşelerinde, üçgenin iç açılarıyla ters durumda bulunan üç açının toplamı radyan cinsinden nedir?', 'π radyan', ['π/2 radyan', '3π/2 radyan', '2π radyan'], 'Ters açıların ölçüleri birbirine eşit olduğundan üç köşedeki dış-ters açıların toplamı üçgenin iç açıları toplamına yani 180° = π radyana eşittir.'),
  ('Herhangi bir üçgenin aynı köşesine ait iç açıortay doğrusu ile dış açıortay doğrusu arasındaki açının türü ve ölçüsü nedir?', 'Dik açı (90 derece)', ['Dar açı (45 derece)', 'Dar açı (60 derece)', 'Geniş açı (120 derece)'], 'Komşu bütünler iki açının toplamı 180° olduğundan yarılarının toplamı 90° eder; bu nedenle iç ve dış açıortaylar her zaman dik kesişir.'),
  ('m(A) = 40° olan ikizkenar bir ABC üçgeninde (|AB| = |AC|), B köşesi kendi iç açıortayı olan [BD] boyunca değil, A tepe açısının açıortayı [AH] boyunca katlandığında B noktası hangi noktayla çakışır?', 'C köşesiyle çakışır', ['Ağırlık merkeziyle çakışır', 'A köşesiyle çakışır', '[AC] kenarının ortasıyla çakışır'], '|AB| = |AC| ikizkenar üçgeninde tepe açısının açıortayı [AH] simetri eksenidir; bu doğru boyunca katlandığında B köşesi tam olarak C köşesinin üzerine oturur.'),
  ('Bir üçgende A iç açısı (3x - 12)°, B dış açısı (5x + 8)° ve C iç açısı (x + 28)° olarak verildiğine göre x değişkeninin sayısal değeri kaçtır?', '8', ['6', '10', '12'], 'Bir dış açı komşu olmayan iki iç açının toplamına eşittir: 5x + 8 = (3x - 12) + (x + 28) => 5x + 8 = 4x + 16 => x = 8 bulunur.'),
  ('Uzunlukları 7 cm ve 12 cm olan iki ahşap çıtanın uçlarına üçüncü bir çıta eklenerek üçgen çerçeve yapılacaktır. Üçüncü çıtanın santimetre cinsinden uzunluğu hangi açık aralıkta yer almalıdır?', '(5, 19)', ['(5, 17)', '(6, 18)', '(7, 19)'], 'Üçgen eşitsizliğine göre üçüncü kenar x için |12 - 7| < x < 12 + 7 koşulu geçerlidir; buradan 5 < x < 19 yani (5, 19) açık aralığı bulunur.'),
  ('m(B) = 90° olan bir ABC dik üçgeninin [BC] dik kenarı üzerinde B-D-E-C sıralamasıyla D ve E noktaları işaretleniyor ve A köşesine birleştiriliyor. Oluşan doğru parçalarının uzunluk sıralaması aşağıdakilerden hangisidir?', '|AB| < |AD| < |AE| < |AC|', ['|AC| < |AE| < |AD| < |AB|', '|AD| < |AB| < |AE| < |AC|', '|AB| < |AE| < |AD| < |AC|'], 'B köşesi dik olduğundan dikme ayağı olan B\'den C yönüne uzaklaştıkça Pisagor bağıntısı gereği hipotenüs uzunlukları sürekli büyür: |AB| < |AD| < |AE| < |AC|.'),
  ('Harita üzerinde A, B ve C kasabaları doğrusal olmayan üç nokta oluşturmaktadır. A ile B arası kuş uçuşu 14 km, B ile C arası kuş uçuşu 23 km olduğuna göre A\'dan C\'ye doğrudan yapılacak düz bir yolun tam sayı uzunluğu en az kaç kilometre olabilir?', '10 km', ['8 km', '9 km', '11 km'], 'Üç nokta doğrusal olmadığından üçgen eşitsizliği geçerlidir: |23 - 14| < |AC| < 23 + 14 => 9 < |AC| < 37 bulunur; en küçük tam sayı 10 km olur.'),
  ('Bir dik üçgende dik olmayan iki dar açıdan biri 32° olduğuna göre bu üçgenin kenar uzunluklarını küçükten büyüğe sıralayan bir öğrenci ilk sıraya hangi kenarı yazmalıdır?', '32 derecelik açının karşısındaki dik kenarı', ['58 derecelik açının karşısındaki dik kenarı', '90 derecelik açının karşısındaki hipotenüsü', '32 derecelik açıya komşu olan dik kenarı'], 'Dik üçgenin açıları 32°, 58° ve 90° olduğundan en küçük açı 32 derecedir; en kısa kenar en küçük açının karşısında bulunan dik kenardır.'),
  ('PRS üçgeninde m(P) = 2x + 10°, m(R) = 3x - 20° ve m(S) = x + 40° olarak tanımlanıyor. Bu üçgenin kenar uzunlukları p, r ve s arasındaki doğru sıralama aşağıdakilerden hangisidir?', 'r < p < s', ['p < r < s', 'r < s < p', 's < p < r'], 'İç açılar toplamı 6x + 30° = 180° => x = 25° bulunur. Köşe açıları m(P) = 60°, m(R) = 55° ve m(S) = 65° olduğundan m(R) < m(P) < m(S) ve karşı kenarlar r < p < s sıralamasını izler.'),
  ('Kenar uzunlukları a = 6 birim, b = 8 birim ve c = 11 birim olan bir ABC üçgeninin açılarına göre türü aşağıdakilerden hangisidir?', 'Geniş açılı üçgen', ['Dar açılı üçgen', 'Dik açılı üçgen', 'İkizkenar dik üçgen'], 'En uzun kenarın karesi 11² = 121 iken diğer iki kenarın kareleri toplamı 6² + 8² = 36 + 64 = 100\'dür. 121 > 100 olduğundan C açısı 90 dereceden büyüktür ve üçgen geniş açılıdır.'),
  ('Bir üçgende en uzun kenarın uzunluğu 13 cm olup diğer iki kenarın uzunlukları santimetre cinsinden birer tam sayıdır. Bu üçgenin çevresi en az kaç santimetre olabilir?', '27 cm', ['25 cm', '26 cm', '28 cm'], 'Diğer iki kenarın toplamı b + c > 13 koşulunu sağlamalıdır; tam sayı oldukları için b + c en az 14 cm (örneğin 7 cm ve 7 cm veya 6 cm ve 8 cm) seçilebilir. Çevre en az 13 + 14 = 27 cm olur.'),
  ('İkizkenar bir üçgenin iki kenar uzunluğu 4 cm ve 9 cm olarak bilindiğine göre bu üçgenin çevresi kaç santimetredir?', '22 cm', ['17 cm', '18 cm', '21 cm'], 'Eş kenarlar 4 cm seçilirse 4 + 4 = 8 < 9 olduğundan üçgen eşitsizliği sağlanmaz! Dolayısıyla eş kenarlar zorunlu olarak 9 cm olur ve çevre 9 + 9 + 4 = 22 cm bulunur.'),
  ('Dik kenarlarının uzunlukları 9 cm ve 40 cm olan dik üçgen biçimindeki bir gönyenin hipotenüs kenarı kaç santimetredir?', '41 cm', ['39 cm', '42 cm', '45 cm'], 'Pisagor bağıntısından hipotenüsün karesi 9² + 40² = 81 + 1600 = 1681 olur; √1681 = 41 cm elde edilir.'),
  ('Düz bir zemine dik duran 12 metre yüksekliğindeki bir aydınlatma direğinin tepesinden, direğin tabanına 5 metre uzaklıktaki bir kazığa gergin çelik tel çekiliyor. Kullanılan telin uzunluğu kaç metredir?', '13 metre', ['14 metre', '15 metre', '17 metre'], 'Direk zemine dik olduğundan dik kenarları 5 m ve 12 m olan dik üçgen oluşur; 5² + 12² = 169 eşitliğinden tel uzunluğu 13 metredir.'),
  ('m(B) = 90° olan bir ABC dik üçgeninde [BC] dik kenarı üzerinde alınan bir D noktası için |AB| = 6 cm, |BD| = 8 cm ve |AC| = 3√13 cm eşitlikleri veriliyor. Buna göre |DC| uzunluğu kaç santimetredir?', '1 cm', ['2 cm', '3 cm', '4 cm'], 'ABC dik üçgeninde Pisagor bağıntısından 6² + |BC|² = (3√13)² => 36 + |BC|² = 117 => |BC|² = 81 => |BC| = 9 cm bulunur. |BD| = 8 cm olduğundan |DC| = 9 - 8 = 1 cm olur.'),
  ('A noktasından [BC] tabanına indirilen dikme ayağı H olan bir ABC üçgeninde |AB| = 10 birim, |BH| = 6 birim ve |HC| = 15 birim olduğuna göre |AC| kenarının uzunluğu kaç birimdir?', '17 birim', ['16 birim', '18 birim', '19 birim'], 'ABH dik üçgeninde yükseklik |AH| = √(10² - 6²) = 8 birim bulunur. AHC dik üçgeninde ise |AC| = √(8² + 15²) = 17 birim elde edilir.'),
  ('m(BAC) = 90° olan bir ABC dik üçgeninde dik köşeden hipotenüse indirilen dikmenin ayağı H noktasıdır. |BH| = 4 cm ve |HC| = 9 cm olduğuna göre |AH| yüksekliği kaç santimetredir?', '6 cm', ['5 cm', '6,5 cm', '8 cm'], 'Öklid yükseklik bağıntısına göre h² = p · k eşitliğinden |AH|² = 4 · 9 = 36 ve |AH| = 6 cm elde edilir.'),
  ('Dik köşesi K olan bir KLM dik üçgeninde hipotenüse ait yükseklik [KH] çiziliyor. |KL| = 6 birim ve |LH| = 3 birim olarak ölçüldüğüne göre |HM| uzunluğu kaç birimdir?', '9 birim', ['6 birim', '8 birim', '12 birim'], 'Öklid dik kenar bağıntısından |KL|² = |LH| · |LM| => 6² = 3 · (3 + |HM|) => 36 = 9 + 3|HM| => |HM| = 9 birim bulunur.'),
  ('Dik kenarları 15 cm ve 20 cm olan dik üçgen şeklindeki bir metal levhanın dik köşesinden hipotenüs kenarına olan en kısa uzaklık kaç santimetredir?', '12 cm', ['10 cm', '12,5 cm', '14 cm'], '15-20-25 dik üçgeninde hipotenüs 25 cm\'dir. Öklid alan-yükseklik bağıntısından a · h = b · c => 25 · h = 15 · 20 => h = 300 / 25 = 12 cm bulunur.'),
  ('m(B) = 90° olan bir ABC dik üçgeninde hipotenüse ait kenarortay uzunluğu |BD| = 8,5 cm ve |AB| = 8 cm olduğuna göre |BC| dik kenarının uzunluğu kaç santimetredir?', '15 cm', ['12 cm', '14 cm', '16 cm'], 'Dik üçgende muhteşem üçlü özelliğinden hipotenüs |AC| = 2 · |BD| = 17 cm olur. Pisagor bağıntısından |BC| = √(17² - 8²) = 15 cm bulunur.'),
  ('Hipotenüs uzunluğu 26 birim olan bir dik üçgenin dik köşesini hipotenüsün orta noktasına birleştiren doğru parçasının uzunluğu kaç birimdir?', '13 birim', ['10 birim', '12 birim', '13√2 birim'], 'Muhteşem üçlü teoremine göre dik üçgende hipotenüse ait kenarortayın uzunluğu hipotenüs uzunluğunun yarısına yani 26 / 2 = 13 birime eşittir.'),
  ('İç açıları 30°, 60° ve 90° olan bir dik üçgende 60 derecelik açının karşısındaki dik kenarın uzunluğu 9 cm olduğuna göre hipotenüs uzunluğu kaç santimetredir?', '6√3 cm', ['9√3 cm', '12 cm', '18 cm'], '60° karşısındaki kenar a√3 = 9 cm ise 30° karşısındaki kenar a = 9/√3 = 3√3 cm olur; hipotenüs bunun iki katı olan 6√3 cm bulunur.'),
  ('Hipotenüs uzunluğu 14√2 birim olan ikizkenar bir dik üçgenin çevre uzunluğu kaç birimdir?', '28 + 14√2 birim', ['14 + 28√2 birim', '42 birim', '42√2 birim'], '45°-45°-90° dik üçgeninde hipotenüs a√2 = 14√2 birim olduğundan dik kenarların her biri 14 birimdir; çevre 14 + 14 + 14√2 = 28 + 14√2 birim olur.'),
  ('Dar açılarından biri 15° olan bir dik üçgenin hipotenüs uzunluğu 24 cm ise bu üçgende dik köşeden hipotenüse indirilen yüksekliğin uzunluğu kaç santimetredir?', '6 cm', ['4 cm', '4√3 cm', '8 cm'], '15°-75°-90° özel dik üçgeninde hipotenüse ait yükseklik hipotenüs uzunluğunun dörtte birine eşittir: h = 24 / 4 = 6 cm.'),
  ('Eşit kenarlarının uzunluğu 17 cm ve taban uzunluğu 16 cm olan ikizkenar üçgen biçimindeki bir levhanın tepe noktasından tabana indirilen yüksekliği kaç santimetredir?', '15 cm', ['12 cm', '13 cm', '14 cm'], 'İkizkenar üçgende tabana indirilen dikme tabanı 8 cm ve 8 cm olarak iki eş parçaya böler; 8-15-17 dik üçgeninden yükseklik 15 cm çıkar.'),
  ('|AB| = |AC| olan ikizkenar bir ABC üçgeninin [BC] tabanı üzerinde alınan rastgele bir P noktasından eş yan kenarlara indirilen dikmelerin uzunlukları 4,2 cm ve 5,8 cm olarak ölçülüyor. Buna göre C köşesinden [AB] kenarına indirilen yüksekliğin uzunluğu kaç santimetredir?', '10 cm', ['9 cm', '9,6 cm', '11,6 cm'], 'İkizkenar üçgenin tabanı üzerindeki bir noktadan eş kenarlara indirilen dikmelerin toplamı, eş kenarlardan birine ait yüksekliğe eşittir: 4,2 + 5,8 = 10 cm.'),
  ('Bir kenar uzunluğu 12 cm olan eşkenar üçgen şeklindeki bir trafik levhasının yüksekliği kaç santimetredir?', '6√3 cm', ['4√3 cm', '6√2 cm', '8√3 cm'], 'Kenarı a olan eşkenar üçgenin yüksekliği a√3 / 2 formülüyle bulunur: 12√3 / 2 = 6√3 cm.'),
  ('Yüksekliği 9 cm olan eşkenar bir üçgenin çevre uzunluğu kaç santimetredir?', '18√3 cm', ['12√3 cm', '24√3 cm', '27 cm'], 'Yükseklik a√3 / 2 = 9 cm eşitliğinden bir kenar a = 18 / √3 = 6√3 cm olur; çevre 3a = 18√3 cm olarak hesaplanır.'),
  ('Kenar uzunlukları 3 metre, 4 metre ve 5 metre olan kapalı halka şeklindeki düğümlü ipi gererek dik açı elde etme yöntemini arazi ölçümlerinde kullanan antik uygarlık hangisidir?', 'Eski Mısır', ['İnka İmparatorluğu', 'Vikingler', 'Aztekler'], 'Nil taşkınları sonrası tarla sınırlarını dik açılarla yeniden belirlemek için 12 eşit aralıklı (3-4-5) düğümlü halat gerici (harpedonaptai) tekniği Eski Mısırlılar tarafından kullanılmıştır.'),
  ('Düzlemdeki bir sokak kavşağında birbirine dik kesişen iki caddeden birindeki A noktasında bulunan kurye kavşağa 160 metre, diğer caddedeki B noktasında bulunan müşteri ise kavşağa 120 metre uzaklıktadır. Kurye ile müşteri arasındaki doğrusal mesafe kaç metredir?', '200 metre', ['180 metre', '220 metre', '240 metre'], '3-4-5 özel dik üçgeninin 40 katı olan 120-160-200 üçgeninden kurye ile müşteri arasındaki kuş uçuşu uzaklık 200 metredir.'),
  ('Bir ekranın boyutu köşegen uzunluğunun inç cinsinden değeriyle ifade edilir. En-boy kenar uzunlukları 16 inç ve 12 inç olan dikdörtgen bir monitörün ekran boyutu kaç inçtir?', '20 inç', ['18 inç', '21 inç', '24 inç'], 'Dikdörtgenin iki kenarı ve köşegeni bir dik üçgen oluşturur; √(16² + 12²) = √(256 + 144) = √400 = 20 inç bulunur.'),
  ('Düz bir zemine dik olan duvarın dibinden 6 metre uzağa alt ucu yerleştirilen 10 metrelik kalasın tam orta noktasından zemine sarkıtılan çekül ipinin uzunluğu kaç metredir?', '4 metre', ['3 metre', '4,5 metre', '5 metre'], 'Kalasın üst ucu yerden √(10² - 6²) = 8 metre yüksektedir. Kalasın orta noktasından zemine inen dikme, dik üçgenin orta tabanı olduğundan yüksekliğin yarısına yani 8 / 2 = 4 metreye eşittir.'),
  ('Üç iç açısının ölçüleri 120°, 30° ve 30° olan ikizkenar bir üçgenin eş olan yan kenarlarından biri 7√3 birim ise 120 derecelik açının karşısındaki uzun kenar kaç birimdir?', '21 birim', ['14√3 birim', '18 birim', '21√3 birim'], '30°-30°-120° özel ikizkenar üçgeninde 120° karşısındaki kenar, eş kenarlardan birinin √3 katına eşittir: 7√3 · √3 = 21 birim.'),
  ('m(A) = 90° olan bir ABC dik üçgeninin hipotenüsü üzerine dışarıya doğru çizilen karenin alanı 169 cm², dik kenarlarından biri üzerine çizilen karenin alanı ise 25 cm²\'dir. Diğer dik kenar üzerine çizilecek eşkenar üçgenin bir kenarı kaç santimetredir?', '12 cm', ['10 cm', '13 cm', '14 cm'], 'Pisagor teoreminin geometrik yorumuna göre dik kenarlar üzerindeki karelerin alanları toplamı hipotenüs üzerindeki karenin alanına eşittir: 25 + b² = 169 => b² = 144 => b = 12 cm bulunur.'),
  ('Aynı düzlemde [AC] hipotenüsü ortak olan ABC ve ADC dik üçgenlerinde m(ABC) = m(ADC) = 90°\'dir. |AB| = 7 cm, |BC| = 24 cm ve |AD| = 15 cm olduğuna göre |DC| uzunluğu kaç santimetredir?', '20 cm', ['16 cm', '18 cm', '22 cm'], 'ABC dik üçgeninde 7-24-25 özelliğinden ortak hipotenüs |AC| = 25 cm olur. ADC dik üçgeninde |DC| = √(25² - 15²) = 20 cm bulunur.'),
  ('Dar açılı bir ABC üçgeninde B ve C köşelerinden karşı kenarlara indirilen yükseklikler |BE| = |CF| birbirine eşit ve 8 cm, |BC| tabanı ise 10 cm\'dir. [AB] kenarı üzerindeki yükseklik ayağı F için |BF| uzunluğu kaç santimetredir?', '6 cm', ['4 cm', '5 cm', '4√3 cm'], 'BFC dik üçgeninde m(BFC) = 90°, hipotenüs |BC| = 10 cm ve dik kenar |CF| = 8 cm olduğundan Pisagor bağıntısıyla |BF| = √(10² - 8²) = 6 cm bulunur.'),
  ('Bir eşkenar üçgenin bir kenar uzunluğu ile yüksekliğinin çarpımı 18√3 cm² olduğuna göre bu eşkenar üçgenin çevresi kaç santimetredir?', '18 cm', ['12 cm', '12√3 cm', '24 cm'], 'Kenarı a olan eşkenar üçgenin yüksekliği a√3 / 2 olduğundan a · (a√3 / 2) = 18√3 => a² = 36 => a = 6 cm ve çevre 3a = 18 cm bulunur.'),
  ('Birim kareli (1x1) bir ızgara kağıt üzerinde A köşesi (1, 2) ve B köşesi (9, 8) koordinatlarına karşılık gelen ızgara düğümlerine işaretleniyor. [AB] doğru parçasının uzunluğu kaç birimdir?', '10 birim', ['9 birim', '11 birim', '14 birim'], 'Yatayda 9 - 1 = 8 birim, düşeyde 8 - 2 = 6 birim fark bulunduğundan Pisagor bağıntısıyla |AB| = √(8² + 6²) = 10 birim hesaplanır.'),
  ('Dik kenarlarının uzunlukları 5 cm ve 5√3 cm olan bir dik üçgenin kısa dik kenarını gören dar açısının ölçüsü kaç derecedir?', '30 derece', ['15 derece', '45 derece', '60 derece'], 'Dik kenarlar a = 5 cm ve a√3 = 5√3 cm oranında olduğundan hipotenüs 10 cm olur; bu üçgen 30°-60°-90° üçgenidir ve kısa dik kenarı gören açı 30 derecedir.'),
  ('Uzunluğu 20 cm olan gergin bir tel tam ortasından 90 derecelik açıyla büküldüğünde telin iki uç noktası arasındaki en kısa uzaklık kaç santimetredir?', '10√2 cm', ['10 cm', '10√3 cm', '15 cm'], 'Tel ortasından büküldüğünde dik kenarları 10 cm ve 10 cm olan ikizkenar bir dik üçgen oluşur; uçlar arasındaki uzaklık hipotenüs olan 10√2 cm\'dir.'),
  ('ABC ≅ DEF üçgen eşliği verildiğinde |AB| = 7 cm, |EF| = 11 cm ve |AC| = 9 cm olarak ölçülüyor. Buna göre DEF üçgeninin çevre uzunluğu kaç santimetredir?', '27 cm', ['25 cm', '26 cm', '29 cm'], 'Eşlik sıralamasına göre |DE| = |AB| = 7 cm, |EF| = 11 cm ve |DF| = |AC| = 9 cm olur; DEF üçgeninin çevresi 7 + 11 + 9 = 27 cm bulunur.'),
  ('KLM ve PRS üçgenleri arasında KLM ≅ PRS eşliği tanımlanmıştır. m(K) = 48° ve m(S) = 67° olduğuna göre m(R) açısının ölçüsü kaç derecedir?', '65°', ['55°', '63°', '75°'], 'Harf eşleşmesinden m(P) = m(K) = 48° ve m(S) = 67° olduğundan PRS üçgeninde m(R) = 180° - (48° + 67°) = 65° elde edilir.'),
  ('İki üçgenin üçer iç açısının karşılıklı olarak birbirine eşit olması, bu iki üçgen hakkında aşağıdaki yargılardan hangisini tek başına garanti eder?', 'Üçgenlerin birbirine benzer olduğunu', ['Üçgenlerin çevrelerinin eşit olduğunu', 'Üçgenlerin alanlarının çakıştığını', 'Üçgenlerin birbirine eş olduğunu'], 'Açı-Açı-Açı (AAA) koşulu kenar uzunluklarının eşitliğini değil orantılılığını zorunlu kılar; bu nedenle eşliği değil benzerliği garanti eder.'),
  ('[AB] ve [CD] doğru parçaları orta noktaları olan O noktasında kesişmektedir. A ile C ve B ile D noktaları birleştirildiğinde oluşan AOC ve BOD üçgenlerinin eşliği hangi teoreme doğrudan dayanır?', 'Kenar-Açı-Kenar (KAK) eşliği', ['Açı-Kenar-Açı (AKA) eşliği', 'Kenar-Kenar-Kenar (KKK) eşliği', 'Hipotenüs-Dik kenar eşliği'], '|AO| = |OB|, |CO| = |OD| ve aralarındaki ters açılar m(AOC) = m(BOD) eşit olduğundan doğrudan KAK eşlik kuralı sağlanır.'),
  ('[DE] // [BC] olacak biçimde çizilen ABC üçgeninde D ∈ [AB] ve E ∈ [AC] noktaları veriliyor. |AD| = 4 birim, |DB| = 6 birim ve |DE| = 10 birim olduğuna göre |BC| tabanının uzunluğu kaç birimdir?', '25 birim', ['15 birim', '20 birim', '24 birim'], 'Temel benzerlik teoreminde parça-bütün oranı kullanılır: |AD| / |AB| = |DE| / |BC| => 4 / (4 + 6) = 10 / |BC| => 4 / 10 = 10 / |BC| => |BC| = 25 birim elde edilir.'),
  ('Birbirine paralel d1, d2 ve d3 doğrularını kesen iki farklı doğrudan birincisi üzerinde ayrılan ardışık parçalar 5 cm ve 15 cm uzunluğundadır. İkinci kesen doğru üzerinde d1 ile d3 arasında kalan toplam uzunluk 28 cm olduğuna göre bu doğru üzerindeki kısa parça kaç santimetredir?', '7 cm', ['6 cm', '8 cm', '9 cm'], 'Birinci Tales teoremine göre paralel doğrular kesenler üzerinde orantılı parçalar ayırır: 5 / 15 = 1 / 3 oranı olduğundan 28 cm\'lik uzunluk k ve 3k olarak bölünür; 4k = 28 => k = 7 cm olur.'),
  ('Üçgen biçimindeki bir yelkenin [AB] kenarının orta noktası D ve [AC] kenarının orta noktası E birleştirilerek destek çıtası takılıyor. |DE| = 3x - 2 dm ve |BC| = 4x + 10 dm olduğuna göre |BC| kenarı kaç desimetredir?', '38 dm', ['19 dm', '34 dm', '42 dm'], '[DE] orta taban olduğundan |BC| = 2 · |DE| => 4x + 10 = 2(3x - 2) => 2x = 14 => x = 7 bulunur; |BC| = 4·7 + 10 = 38 dm olur.'),
  ('Kum saati biçimindeki geometrik şekilde [AB] // [CD] olup [AD] ve [BC] doğru parçaları K noktasında kesişmektedir. |AK| = 6 cm, |KD| = 15 cm ve |AB| = 8 cm olduğuna göre |CD| uzunluğu kaç santimetredir?', '20 cm', ['16 cm', '18 cm', '24 cm'], 'Kelebek benzerliğinden |AK| / |KD| = |AB| / |CD| => 6 / 15 = 8 / |CD| => 2 / 5 = 8 / |CD| => |CD| = 20 cm elde edilir.'),
  ('Boyu 1,8 metre olan bir kişi, yerden 5,4 metre yükseklikteki sokak lambasının direğinden doğrusal olarak 4 metre uzaklıkta durmaktadır. Kişinin düz zemin üzerinde oluşan gölgesinin uzunluğu kaç metredir?', '2 metre', ['1,5 metre', '2,4 metre', '3 metre'], 'Gölge uzunluğuna x metre denirse temel benzerlikten x / (x + 4) = 1,8 / 5,4 = 1 / 3 => 3x = x + 4 => x = 2 metre elde edilir.'),
  ('Güneşli bir öğleden sonra yatay zemine dik duran 1,5 metre boyundaki bir çubuğun gölgesi 2,4 metre olarak ölçülüyor. Aynı anda düz zemine dik bir çınar ağacının gölgesi 16,8 metre ölçüldüğüne göre ağacın boyu kaç metredir?', '10,5 metre', ['9,6 metre', '11,2 metre', '12 metre'], 'Güneş ışınları paralel kabul edildiğinden dik üçgenler benzerdir: Ağaç boyu / 16,8 = 1,5 / 2,4 = 5 / 8 => Ağaç boyu = 16,8 · 5 / 8 = 10,5 metre bulunur.'),
  ('Benzer iki üçgenin benzerlik oranı 3/7 olduğuna göre bu iki üçgenin karşılıklı iç açıortaylarının uzunlukları oranı kaçtır?', '3/7', ['9/49', '√3/√7', '6/7'], 'Benzer üçgenlerde karşılıklı kenarortayların, yüksekliklerin, iç açıortayların ve çevrelerin oranı doğrudan benzerlik oranına yani 3/7\'ye eşittir.'),
  ('ABC ~ KLM benzerliği verilen iki üçgende A köşesine ait kenarortay 10 cm, K köşesine ait kenarortay ise 15 cm\'dir. ABC üçgeninin çevresi 34 cm olduğuna göre KLM üçgeninin çevresi kaç santimetredir?', '51 cm', ['45 cm', '48 cm', '68 cm'], 'Benzerlik oranı kenarortaylar oranına eşittir: k = 10 / 15 = 2 / 3. Çevreler oranı da 2 / 3 olduğundan 34 / Çevre(KLM) = 2 / 3 => Çevre(KLM) = 51 cm bulunur.'),
  ('MÖ 6. yüzyılda Mısır\'daki Büyük Piramit\'in (Keops) yüksekliğini, kendi gölge boyunun kendi gerçek boyuna eşit olduğu anı bekleyip piramidin gölgesini ölçerek hesaplayan antik filozof ve matematikçi kimdir?', 'Miletli Thales', ['Samoslu Pisagor', 'İskenderiyeli Öklid', 'Siraküzalı Arşimet'], 'Miletli Thales, güneş ışınlarının 45° açıyla geldiği anda benzer dik üçgenlerde nesne boyu ile gölge boyunun eşitlenmesinden yararlanarak piramidin yüksekliğini ölçmüştür.'),
  ('Çizimlerde ve haritacılıkta bir şekli belirli bir benzerlik oranında büyütmek veya küçültmek amacıyla paralelkenar kollar ve sabit bir odak pimiyle çalışan mekanik çizim aracına ne ad verilir?', 'Pantograf', ['Teodolit', 'Usturlap', 'Sekstant'], 'Pantograf, paralelkenar bağlantıları sayesinde odak noktasından itibaren sabit benzerlik oranı (homoteti) koruyarak şekilleri ölçekli kopyalayan mekanizmadır.'),
  ('Eğim açısı sabit olan doğrusal bir engelli rampasının altına eşit yatay aralıklarla yere dik 4 adet destek dikmesi yerleştirilmiştir (başlangıç zeminde 0 metre, 4. dikme rampanın en üst ucunda). En üstteki 4. dikmenin boyu 1,4 metre olduğuna göre 3. dikmenin boyu kaç santimetredir?', '105 cm', ['95 cm', '100 cm', '112 cm'], 'Temel benzerlikten dikme boyları başlangıç noktasına olan yatay uzaklıkla doğru orantılıdır: h3 / 140 cm = 3 / 4 => h3 = 105 cm bulunur.'),
  ('m(BAC) = 90° olan ABC dik üçgeninde [BC] hipotenüsü üzerindeki D noktasından [AC] kenarına indirilen [DE] dikmesi için |BD| = 10 cm, |DC| = 5 cm ve |DE| = 3 cm veriliyor. Buna göre |AB| dik kenarının uzunluğu kaç santimetredir?', '9 cm', ['6 cm', '8 cm', '12 cm'], '[DE] ⊥ [AC] ve [AB] ⊥ [AC] olduğundan [DE] // [AB] olur. Temel benzerlikten |CD| / |CB| = |DE| / |AB| => 5 / (5 + 10) = 3 / |AB| => 1 / 3 = 3 / |AB| => |AB| = 9 cm bulunur.'),
  ('Üç kenarının orta noktaları birleştirilerek oluşturulan orta taban üçgeni (medial üçgen) ile başlangıçtaki ana üçgen arasındaki benzerlik oranı kaçtır?', '1/2', ['1/3', '1/4', '2/3'], 'Medial üçgenin her bir kenarı ana üçgenin karşılıklı kenarının orta tabanı olduğundan kenar uzunlukları yarı yarıyadır ve KKK benzerliğinden benzerlik oranı 1/2 olur.'),
  ('Tepe açıları eşit olan iki farklı ikizkenar üçgen için aşağıdaki ifadelerden hangisi her zaman doğrudur?', 'Üçgenler kesinlikle birbirine benzerdir', ['Üçgenlerin taban uzunlukları eşittir', 'Üçgenlerin alanları birbirine eşittir', 'Üçgenler yalnızca dik iseler benzerdir'], 'Tepe açıları α olan iki ikizkenar üçgenin taban açıları da (180° - α)/2 olarak birbirine eşit çıkacağından Açı-Açı benzerlik teoremi gereği daima benzerdirler.'),
  ('Tüm eşkenar üçgenlerin kendi aralarındaki eşlik ve benzerlik ilişkisi için hangisi söylenebilir?', 'Kenar uzunluklarından bağımsız olarak tümü benzerdir', ['Yalnızca çevreleri eşit olanlar benzerdir', 'Kenarları tam sayı olanlar birbirine eştir', 'Benzerlik oranları her zaman bire eşittir'], 'Her eşkenar üçgenin tüm iç açıları 60° olduğundan AAA benzerlik kriteri uyarınca düzlemdeki bütün eşkenar üçgenler birbirine benzerdir.'),
  ('İki dik üçgenin birer dar açısının ölçüsü 37° olarak biliniyorsa bu iki dik üçgen için aşağıdakilerden hangisi kesinlikle doğrudur?', 'Karşılıklı kenar uzunlukları orantılıdır', ['Hipotenüs uzunlukları birbirine eşittir', 'Dik kenarlarının toplamları aynıdır', 'İç teğet çember yarıçapları eşittir'], 'Birer açıları 90° ve birer dar açıları 37° olan iki dik üçgen AA kriterine göre benzerdir; dolayısıyla karşılıklı kenar uzunlukları orantılıdır.'),
  ('Aynı düzlemdeki ABC ve DEF üçgenlerinde |AB| / |DE| = |BC| / |EF| = 3/4 ve m(B) = m(E) eşitlikleri sağlandığına göre |AC| = 18 cm iken |DF| uzunluğu kaç santimetredir?', '24 cm', ['21 cm', '22,5 cm', '27 cm'], 'İki kenar orantılı ve aralarındaki açılar eşit (m(B) = m(E)) olduğundan KAK benzerlik teoremiyle ABC ~ DEF olur; 18 / |DF| = 3 / 4 => |DF| = 24 cm bulunur.'),
  ('Dik açılı bir ABC üçgeninde (m(A) = 90°), hipotenüsün orta noktası D ve [AB] dik kenarının orta noktası E olarak işaretleniyor. |AC| = 22 birim olduğuna göre |DE| doğru parçasının uzunluğu kaç birimdir?', '11 birim', ['9 birim', '10 birim', '11√2 birim'], 'D ve E noktaları sırasıyla [BC] ve [AB] kenarlarının orta noktaları olduğundan [DE] orta tabandır ve |AC| kenarının yarısına eşittir: 22 / 2 = 11 birim.'),
  ('Bir ABC üçgeninde [AB] kenarının orta noktası K\'dan [BC] tabanına paralel çizilen doğru [AC] kenarını L noktasında kesiyor. |AL| = 5x - 7 cm ve |LC| = 2x + 8 cm olduğuna göre |AC| kenarının toplam uzunluğu kaç santimetredir?', '36 cm', ['18 cm', '30 cm', '42 cm'], 'Bir kenarın orta noktasından tabana paralel çizilen doğru karşı kenarı da iki eş parçaya böler: 5x - 7 = 2x + 8 => 3x = 15 => x = 5 olur. |AL| = |LC| = 18 cm olduğundan |AC| = 36 cm bulunur.'),
  ('Merdiven şeklindeki bir kitaplığın yan destek çıtaları üstte A noktasında birleşmekte ve yere paralel üç raf bu çıtalar arasına monte edilmektedir. A tepe noktasından birinci rafa uzaklık 30 cm, birinci raftan ikinci rafa 20 cm, ikinci raftan üçüncü rafa 25 cm\'dir. En üstteki birinci rafın uzunluğu 24 cm olduğuna göre en alttaki üçüncü rafın uzunluğu kaç santimetredir?', '60 cm', ['50 cm', '56 cm', '64 cm'], 'A noktasından raflara olan kenar uzunlukları sırasıyla 30 cm, 50 cm ve 75 cm\'dir. Temel benzerlikten 24 / L3 = 30 / 75 = 2 / 5 => L3 = 60 cm bulunur.'),
  ('Üçgen biçimindeki bir kağıtta [AB] kenarı 4 eş parçaya, [AC] kenarı da 4 eş parçaya bölünerek karşılıklı bölme noktaları tabana paralel üç doğru parçasıyla birleştiriliyor. En kısa paralel parçanın uzunluğu 3,5 cm olduğuna göre üç paralel parçanın uzunlukları toplamı kaç santimetredir?', '21 cm', ['17,5 cm', '24,5 cm', '28 cm'], 'Temel benzerlikten paralel parçaların uzunlukları 1k, 2k ve 3k ile orantılıdır. En kısa parça k = 3,5 cm olduğundan üç parçanın toplamı 6k = 6 · 3,5 = 21 cm olur.'),
  ('Bir projektör perdesine 4 metre uzaklıktayken perde üzerinde kenarı 1,2 metre olan eşkenar üçgen biçiminde ışıklı bölge oluşturuyor. Projektör aynı doğrultuda perdeden 2 metre daha geriye çekilirse perde üzerindeki eşkenar üçgenin bir kenarı kaç metre olur?', '1,8 metre', ['1,5 metre', '1,6 metre', '2,4 metre'], 'Projektörün perdeye uzaklığı 4 metreden 4 + 2 = 6 metreye çıktığından benzerlik oranı 6 / 4 = 3 / 2 olur; yeni kenar uzunluğu 1,2 · (3/2) = 1,8 metre bulunur.'),
  ('Bir ABC üçgeninde D ∈ [AB] ve E ∈ [AC] olup [DE] // [BC] paralelliği veriliyor. |AD| = x + 1, |DB| = 4, |AE| = 2x - 1 ve |EC| = 6 olduğuna göre x kaçtır?', '5', ['3', '4', '6'], 'Temel orantı teoreminden (x + 1) / 4 = (2x - 1) / 6 => 6x + 6 = 8x - 4 => 2x = 10 => x = 5 elde edilir.'),
  ('Birim kareli zeminde köşeleri ızgara noktalarında bulunan ve dik kenarları 3 birim ile 4 birim olan bir dik üçgene benzer, hipotenüsü 15 birim olan başka bir üçgen çizildiğinde bu yeni üçgenin kısa dik kenarı kaç birim olur?', '9 birim', ['8 birim', '10 birim', '12 birim'], 'İlk dik üçgen 3-4-5 üçgenidir. Benzer yeni üçgenin hipotenüsü 15 birim olduğundan benzerlik oranı 15 / 5 = 3 olur; kısa dik kenar 3 · 3 = 9 birimdir.'),
  ('Çevresi 45 cm olan bir ABC üçgeninin kenarlarıyla orantılı kenarlara sahip benzer bir PQR üçgeninin en uzun kenarı, ABC\'nin en uzun kenarından %40 daha uzundur. PQR üçgeninin çevresi kaç santimetredir?', '63 cm', ['59 cm', '60 cm', '65 cm'], 'En uzun kenar %40 daha uzunsa benzerlik oranı 1,4 = 7/5 olur. Çevreler oranı da benzerlik oranına eşit olduğundan PQR\'nin çevresi 45 · 1,4 = 63 cm bulunur.'),
  ('Bir üçgenin üç iç açıortayının tek bir noktada kesişmesiyle elde edilen bu kesişim noktası için aşağıdakilerden hangisi her zaman doğrudur?', 'Üçgenin üç kenarına da eşit dik uzaklıktadır', ['Üçgenin üç köşesine de eşit doğrusal uzaklıktadır', 'Geniş açılı üçgenlerde üçgensel bölgenin dışında yer alır', 'Her kenarı köşeden itibaren bire iki oranında böler'], 'İç açıortayların kesim noktası üçgenin iç teğet çemberinin merkezidir; açıortay üzerindeki nokta kollarına eşit uzaklıkta olduğundan üç kenara da dik uzaklığı eşittir ve daima üçgenin iç bölgesindedir.'),
  ('ABC üçgeninde [AD] iç açıortayı [BC] kenarını D noktasında kesmektedir. |AB| = 10 cm, |AC| = 15 cm ve |BC| = 20 cm olduğuna göre |BD| uzunluğu kaç santimetredir?', '8 cm', ['6 santimetre', '10 santimetre', '12 santimetre'], 'İç açıortay teoremine göre |BD| / |DC| = |AB| / |AC| = 10 / 15 = 2 / 3 olur. |BD| = 2k ve |DC| = 3k alınırsa 5k = 20 cm => k = 4 cm ve |BD| = 8 cm bulunur.'),
  ('Bir üçgende bir köşeden çıkan iç açıortay doğrusu ile aynı köşeden çıkan dış açıortay doğrusu arasındaki açının ölçüsü kaç derecedir?', '90°', ['45 derece', '60 derece', '120 derece'], 'Bir köşedeki iç açı ile komşu bütünler dış açının toplamı 180° olduğundan bunların açıortayları arasında kalan açı 180° / 2 = 90° olur.'),
  ('G noktası ABC üçgeninin ağırlık merkezi ve [AD] kenarortay olmak üzere |GD| = 7 cm ise |AD| kenarortayının toplam uzunluğu kaç santimetredir?', '21 cm', ['14 santimetre', '24 santimetre', '28 santimetre'], 'Ağırlık merkezi kenarortayı köşeye 2 birim, kenara 1 birim uzaklıkta böler: |AG| = 2 · |GD| = 14 cm ve |AD| = 14 + 7 = 21 cm olur.'),
  ('Geniş açılı bir üçgenin diklik merkezi (yüksekliklerin doğrularının kesişim noktası) üçgene göre hangi bölgede bulunur?', 'Üçgenin dış bölgesinde, geniş açılı köşenin arkasında', ['Üçgenin iç bölgesinde, ağırlık merkeziyle aynı tarafta', 'Geniş açının karşısındaki en uzun kenarın tam ortasında', 'Geniş açıyı oluşturan köşenin tam üzerinde yer alır'], 'Geniş açılı üçgende dar açılı köşelerden karşı kenar doğrularına indirilen dikmeler üçgenin dışına düşer ve uzantıları geniş açılı köşenin arka tarafında, dış bölgede kesişir.'),
  ('Bir üçgenin üç kenar orta dikmesinin kesişim noktası olan O noktası ile ilgili aşağıdakilerden hangisi kesinlikle doğrudur?', 'Üçgenin çevrel çemberinin merkezidir ve köşelere eşit uzaklıktadır', ['Üçgenin iç teğet çemberinin merkezidir ve kenarlara eşit uzaklıktadır', 'Üçgenin alanını eşit altı parçaya bölen kenarortayların kesimidir', 'Her türlü üçgende daima üçgensel bölgenin iç kısmında kalır'], 'Kenar orta dikmeler üzerindeki noktalar uç noktalara eşit uzaklıkta olduğundan kesişim noktası üç köşeye de eşit uzaklıktadır ve çevrel çember merkezini verir.'),
  ('ABC üçgeninde I noktası iç teğet çemberin merkezidir. m(BAC) = 68° olduğuna göre m(BIC) açısının ölçüsü kaç derecedir?', '124°', ['112 derece', '122 derece', '136 derece'], 'İç açıortayların kesim noktası I için m(BIC) = 90° + m(BAC) / 2 bağıntısı geçerlidir: 90° + 68° / 2 = 90° + 34° = 124° elde edilir.'),
  ('Dik kenarları 9 cm ve 12 cm olan bir dik üçgenin iç teğet çemberinin yarıçapı kaç santimetredir?', '3 cm', ['2,5 santimetre', '3,5 santimetre', '4 santimetre'], '9-12-15 dik üçgeninde iç teğet çember yarıçapı r = (dik kenarlar toplamı - hipotenüs) / 2 = (9 + 12 - 15) / 2 = 3 cm olarak hesaplanır.'),
  ('Bir eşkenar üçgenin ağırlık merkezi, iç teğet çember merkezi, çevrel çember merkezi ve diklik merkezi kaç farklı noktadan oluşur?', 'Yalnızca 1 ortak nokta', ['Euler doğrusu üzerinde 2 farklı nokta', 'Doğrusal dizilmiş 3 farklı nokta', 'Birbirinden ayrı 4 farklı nokta'], 'Eşkenar üçgende simetri gereği her köşeden çizilen yükseklik, açıortay, kenarortay ve orta dikme çakışıktır; bu nedenle dört temel merkez tek bir noktada birleşir.'),
  ('Bir üçgende taban uzunluğu %20 artırılıp bu tabana ait yükseklik %25 azaltılırsa üçgenin alanı ilk durumuna göre nasıl değişir?', '%10 azalır', ['%5 oranında azalır', 'Değişmeden aynı kalır', '%5 oranında artar'], 'Taban 1,2 katına, yükseklik 0,75 katına çıkar; yeni alan eski alanın 1,2 · 0,75 = 0,90 katı olduğundan alan %10 azalır.'),
  ('Taban kenarı 16 cm ve bu tabana ait yüksekliği 9 cm olan bir üçgenle eşit alana sahip bir karenin bir kenar uzunluğu kaç santimetredir?', '6√2 cm', ['8 santimetre', '9 santimetre', '12 santimetre'], 'Üçgenin alanı (16 · 9) / 2 = 72 cm²\'dir. Karenin alanı a² = 72 => a = √72 = 6√2 cm bulunur.'),
  ('Geniş açılı bir KLM üçgeninde m(KLM) > 90° olup |LM| = 10 cm\'dir. K köşesinin LM doğrusuna en kısa uzaklığı 7 cm olduğuna göre KLM üçgeninin alanı kaç cm²\'dir?', '35 cm²', ['30 santimetrekare', '45 santimetrekare', '70 santimetrekare'], 'K köşesinin LM doğrusuna en kısa uzaklığı [LM] kenarına ait dış yüksekliktir (h = 7 cm). Alan = (10 · 7) / 2 = 35 cm² hesaplanır.'),
  ('İki kenar uzunluğu 8 cm ve 12 cm, bu iki kenar arasındaki açının ölçüsü 30° olan bir üçgenin alanı kaç santimetrekaredir?', '24 cm²', ['24√3 santimetrekare', '36 santimetrekare', '48 santimetrekare'], 'Sinüs alan formülünden Alan = (1/2) · 8 · 12 · sin(30°) = 48 · (1/2) = 24 cm² bulunur.'),
  ('Bir kenar uzunluğu 8 cm olan eşkenar üçgenin alanı kaç santimetrekaredir?', '16√3 cm²', ['12√3 santimetrekare', '24√3 santimetrekare', '32√3 santimetrekare'], 'Kenarı a olan eşkenar üçgenin alanı (a²√3) / 4 = (64√3) / 4 = 16√3 cm² olarak bulunur.'),
  ('ABC üçgeninde G ağırlık merkezi ve Alan(ABG) = 19 cm² olduğuna göre tüm ABC üçgeninin alanı kaç santimetrekaredir?', '57 cm²', ['38 santimetrekare', '76 santimetrekare', '114 santimetrekare'], 'Ağırlık merkezini üç köşeyle birleştiren doğru parçaları üçgeni alanları birbirine eşit üç üçgene ayırır: Alan(ABC) = 3 · 19 = 57 cm².'),
  ('Bir üçgende üç kenarortayın tamamı çizildiğinde oluşan altı küçük üçgensel bölgeden birinin alanı 6,5 birimkare olduğuna göre başlangıçtaki üçgenin alanı kaç birimkaredir?', '39 birimkare', ['26 birimkare', '32,5 birimkare', '52 birimkare'], 'Üç kenarortay üçgensel bölgeyi eşit alanlı 6 parçaya böler; toplam alan 6 · 6,5 = 39 birimkaredir.'),
  ('Benzer iki üçgenin karşılıklı açıortaylarının uzunlukları oranı 3/5\'tir. Küçük üçgenin alanı 27 cm² olduğuna göre büyük üçgenin alanı kaç santimetrekaredir?', '75 cm²', ['45 santimetrekare', '60 santimetrekare', '90 santimetrekare'], 'Benzer üçgenlerde alanlar oranı benzerlik oranının karesine eşittir: 27 / A = (3/5)² = 9 / 25 => A = 75 cm² bulunur.'),
  ('Köşeleri A, B, C olan bir üçgende |AB| = 8 birim, |AC| = 12 birim ve [AD] iç açıortaydır. Alan(ABD) = 18 birimkare olduğuna göre Alan(ADC) kaç birimkaredir?', '27 birimkare', ['24 birimkare', '30 birimkare', '36 birimkare'], 'İç açıortay tabanı kollarıyla orantılı böldüğünden (veya açıortaydan kollara inen dikmeler eşit olduğundan) alanlar oranı kolların oranına eşittir: 18 / Alan(ADC) = 8 / 12 = 2 / 3 => Alan(ADC) = 27 birimkare bulunur.'),
  ('Bir üçgenin kenarlarının orta noktaları birleştirilerek oluşturulan orta (medial) üçgenin alanı 11 cm² olduğuna göre büyük üçgenin alanı kaç santimetrekaredir?', '44 cm²', ['22 santimetrekare', '33 santimetrekare', '66 santimetrekare'], 'Kenar orta noktalarının birleştirilmesiyle oluşan dört küçük üçgen birbirine eş olup her birinin alanı eşittir; tüm alan 4 · 11 = 44 cm² olur.'),
  ('Birim kareli düzlemde köşelerinin koordinatları A(1, 2), B(7, 2) ve C(4, 8) olan ABC üçgeninin alanı kaç birimkaredir?', '18 birimkare', ['15 birimkare', '21 birimkare', '36 birimkare'], '[AB] kenarı yatay olup uzunluğu 7 - 1 = 6 birimdir. C köşesinin y = 2 doğrusuna dik uzaklığı 8 - 2 = 6 birimdir. Alan = (6 · 6) / 2 = 18 birimkare olur.'),
  ('Köşeleri K(2, 5), L(6, 1) ve M(4, 9) olan üçgenin ağırlık merkezinin koordinatları toplamı kaçtır?', '9', ['8 tam sayı değeri', '10 tam sayı değeri', '12 tam sayı değeri'], 'Ağırlık merkezi G((2+6+4)/3, (5+1+9)/3) = G(4, 5) olup koordinatları toplamı 4 + 5 = 9\'dur.'),
  ('İkizkenar dik üçgenin hipotenüs uzunluğu 10√2 cm olduğuna göre bu üçgenin alanı kaç santimetrekaredir?', '50 cm²', ['25√2 santimetrekare', '50√2 santimetrekare', '100 santimetrekare'], 'İkizkenar dik üçgende hipotenüs a√2 = 10√2 => dik kenar a = 10 cm olur. Alan = (10 · 10) / 2 = 50 cm² bulunur.'),
  ('ABC üçgeninde [AB] ⊥ [AC], [AD] ⊥ [BC] olup |BD| = 4 cm ve |DC| = 9 cm\'dir. Buna göre ABD üçgeninin alanı kaç santimetrekaredir?', '12 cm²', ['18 santimetrekare', '24 santimetrekare', '27 santimetrekare'], 'Öklid yükseklik bağıntısından |AD|² = 4 · 9 = 36 => |AD| = 6 cm olur. Alan(ABD) = (|BD| · |AD|) / 2 = (4 · 6) / 2 = 12 cm² bulunur.'),
  ('ABC eşkenar üçgeninin çevrel çemberinin yarıçapı 6√3 cm olduğuna göre bu üçgenin iç teğet çemberinin yarıçapı kaç santimetredir?', '3√3 cm', ['3 santimetre', '6 santimetre', '4√3 santimetre'], 'Eşkenar üçgende ağırlık merkezi hem çevrel hem iç teğet çember merkezidir ve yüksekliği 2 : 1 oranında böldüğünden R = 2r olur: r = 6√3 / 2 = 3√3 cm.'),
  ('İkizkenar bir üçgende tabana ait kenarortay aynı zamanda aşağıdakilerden hangisi olmak zorundadır?', 'Hem tepe açısının açıortayı hem de tabana ait yükseklik', ['Yan kenarlara ait kenarortaylarla eşit uzunlukta doğru parçası', 'Taban kenarının uzunluğunun tam yarısına eşit uzunlukta parça', 'Yan kenarların orta dikmelerinin taban üzerindeki kesişim noktası'], 'İkizkenar üçgende simetri ekseni olan tepe yüksekliği aynı zamanda kenarortay, açıortay ve tabanın orta dikmesidir (YAK / Dörtlü kuralı).'),
  ('Bir ABC üçgeninde A köşesinden [BC] kenarına inen [AH] doğru parçası hem açıortay hem de yükseklik olup |AB| = 3x - 4 cm ve |AC| = x + 8 cm\'dir. |BC| = 16 cm olduğuna göre ABC üçgeninin çevresi kaç santimetredir?', '44 cm', ['40 santimetre', '42 santimetre', '48 santimetre'], 'Bir köşeden inen doğru parçası hem açıortay hem yükseklikse üçgen ikizkenardır: |AB| = |AC| => 3x - 4 = x + 8 => 2x = 12 => x = 6 cm. Yan kenarlar 14 cm ve 14 cm olup çevre 14 + 14 + 16 = 44 cm\'dir.'),
  ('Bir ABC üçgeninde [AD] kenarortayı üzerinde |AE| = 2 · |ED| olacak biçimde bir E noktası seçiliyor. E noktası bu üçgen için aşağıdakilerden hangisidir?', 'Üçgenin ağırlık merkezi', ['Üçgenin diklik merkezi noktası', 'Üçgenin iç teğet çember merkezi', 'Üçgenin çevrel çember merkezi'], 'Bir kenarortayı köşeden itibaren 2 : 1 oranında bölen tek nokta üçgenin ağırlık merkezidir.'),
  ('Üçgen biçimindeki bir yelkenin köşeleri A, B ve C olup m(ABC) = 135°, |AB| = 6√2 metre ve |BC| = 5 metredir. Bu yelkenin kumaş yüzey alanı kaç metrekaredir?', '15 m²', ['12 metrekare', '15√2 metrekare', '30 metrekare'], 'Sinüs alan formülüyle Alan = (1/2) · 6√2 · 5 · sin(135°) = 15√2 · (√2 / 2) = 15 m² bulunur.'),
  ('ABC üçgeninde m(BAC) > 90° (geniş açı), |AB| = 9 cm ve |AC| = 12 cm\'dir. |BC| kenarının santimetre cinsinden alabileceği en küçük tam sayı değeri kaçtır?', '16 cm', ['14 santimetre', '15 santimetre', '20 santimetre'], 'm(BAC) > 90° olduğundan |BC|² > 9² + 12² = 81 + 144 = 225 => |BC| > 15 cm olur; üçgen eşitsizliğinden de |BC| < 9 + 12 = 21 cm olduğundan en küçük tam sayı değeri 16 cm\'dir.'),
  ('ABC çeşitkenar üçgeninde iç açılar arasında m(A) > m(B) > m(C) sıralaması vardır ve m(B) = 62° olarak verilmiştir. Buna göre m(A) açısının derece cinsinden alabileceği en küçük tam sayı değeri kaçtır?', '63°', ['60 derece', '61 derece', '64 derece'], 'm(B) = 62° iken m(A) + m(C) = 118° olur. m(A) = 63° seçildiğinde m(C) = 55° olur ve 63° > 62° > 55° sıralaması sağlanır; dolayısıyla en küçük tam sayı değeri 63°\'dir.'),
  ('Bir ikizkenar üçgenin taban açılarından birinin ölçüsü, tepe açısının ölçüsünün 2 katından 15° eksiktir. Bu üçgenin tepe açısı kaç derecedir?', '42°', ['38 derece', '40 derece', '45 derece'], 'Tepe açısı x alınırsa eş taban açılarının her biri 2x - 15° olur: x + 2(2x - 15°) = 180° => 5x - 30° = 180° => 5x = 210° => x = 42° bulunur.'),
  ('Bir üçgenin dış açılarının ölçüleri 4, 5 ve 6 sayılarıyla doğru orantılı olduğuna göre bu üçgenin en küçük iç açısının ölçüsü kaç derecedir?', '36°', ['24 derece', '48 derece', '60 derece'], 'Dış açılar toplamı 360° olduğundan 4k + 5k + 6k = 15k = 360° => k = 24° olur. En büyük dış açı 6 · 24° = 144° olup ona komşu olan en küçük iç açı 180° - 144° = 36°\'dir.'),
  ('ABC üçgeninde [BD] doğru parçası [AC] kenarı üzerindeki D noktasında sonlanmakta ve |AB| = |BD| = |DC| eşitlikleri sağlanmaktadır. m(ACB) = 34° olduğuna göre m(BAC) açısı kaç derecedir?', '68°', ['56 derece', '62 derece', '78 derece'], '|BD| = |DC| olduğundan m(DBC) = m(DCB) = 34° ve dış açı m(BDA) = 34° + 34° = 68° olur. |AB| = |BD| olduğundan ABD ikizkenar üçgeninde m(BAD) = m(BDA) = 68° bulunur.'),
  ('Konveks olmayan (içbükey / bumerang biçimli) ABDC dörtgeninde D köşesi ABC üçgeninin iç bölgesindedir. m(BAC) = 48°, m(ABD) = 27° ve m(ACD) = 35° olduğuna göre D köşesindeki dar taraflı m(BDC) açısı kaç derecedir?', '110°', ['98 derece', '102 derece', '120 derece'], 'Bumerang (şalvar) kuralına göre içbükey köşedeki dış açı m(BDC) = m(BAC) + m(ABD) + m(ACD) = 48° + 27° + 35° = 110° bulunur.'),
  ('ABC dik üçgeninde m(A) = 90°, |AB| = 9 cm ve |AC| = 12 cm\'dir. A köşesinden [BC] hipotenüsüne indirilen [AH] yüksekliğinin uzunluğu kaç santimetredir?', '36/5 cm', ['6 santimetre', '7 santimetre', '39/5 santimetre'], '9-12-15 dik üçgeninde hipotenüs |BC| = 15 cm\'dir. Öklid alan bağıntısından |AH| · 15 = 9 · 12 => |AH| = 108 / 15 = 36/5 cm elde edilir.'),
  ('Aralarında yatayda 24 metre mesafe bulunan ve zemine dik duran iki direkten birinin boyu 11 metre, diğerinin boyu 21 metredir. Bu iki direğin tepe noktaları arasına gerilecek en kısa kablonun uzunluğu kaç metredir?', '26 metre', ['25 tam metre', '28 tam metre', '30 tam metre'], 'Kısa direğin tepesinden uzun direğe yatay dikme çizildiğinde boy farkı 21 - 11 = 10 metre ve yatay mesafe 24 metre olan dik üçgen oluşur (5-12-13\'ün 2 katı olan 10-24-26 üçgeni). Kablo uzunluğu 26 metredir.'),
  ('Benzerlik oranı 2/5 olan iki benzer üçgenin çevreleri toplamı 63 cm olduğuna göre büyük üçgenin çevresi kaç santimetredir?', '45 cm', ['35 santimetre', '40 santimetre', '50 santimetre'], 'Çevreler oranı benzerlik oranına eşittir: 2k + 5k = 7k = 63 => k = 9 cm olup büyük üçgenin çevresi 5 · 9 = 45 cm\'dir.'),
  ('Bir ABC üçgeninde [DE] // [FG] // [BC] olacak biçimde [AB] kenarı üç eşit parçaya bölünmüştür (|AD| = |DF| = |FB|). En üstteki küçük üçgenin alanı 7 cm² olduğuna göre en alttaki FGCB yamuğunun alanı kaç santimetrekaredir?', '35 cm²', ['21 santimetrekare', '28 santimetrekare', '42 santimetrekare'], 'Eşit aralıklı paraleller üçgen alanlarını yukarıdan aşağıya S, 3S, 5S tek sayılarıyla orantılı böler. S = 7 cm² olduğundan en alttaki yamuğun alanı 5S = 5 · 7 = 35 cm² olur.'),
  ('İkizkenar dik üçgen biçimindeki ABC kağıdında m(B) = 90° ve |AB| = |BC| = 12 cm\'dir. [AB] ve [BC] dik kenarlarının orta noktaları D ve E birleştirilerek BDE üçgeni kesilip atılıyor. Geriye kalan yamuğun alanı kaç santimetrekaredir?', '54 cm²', ['36 santimetrekare', '48 santimetrekare', '60 santimetrekare'], 'Başlangıçtaki dik üçgenin alanı (12 · 12) / 2 = 72 cm²\'dir. Kesilen BDE dik üçgeninin dik kenarları 6 cm ve 6 cm olduğundan alanı (6 · 6) / 2 = 18 cm² olur; kalan alan 72 - 18 = 54 cm²\'dir.'),
  ('Bir üçgende taban kenarı sabit tutulup tepe noktası tabana paralel bir doğru boyunca kaydırıldığında üçgenin aşağıdaki niceliklerinden hangisi değişmez?', 'Üçgensel bölgenin alanı', ['Üçgenin toplam çevre uzunluğu', 'Üçgenin iç teğet çember yarıçapı', 'Üçgenin çevrel çember yarıçapı'], 'Tepe noktası tabana paralel doğru üzerinde hareket ederken taban ve tabana ait yükseklik sabit kaldığından alan değişmez; ancak yan kenar uzunlukları ve dolayısıyla çevre ile çember yarıçapları değişir.'),
  ('ABC üçgeninde |AB| = |AC| ikizkenarlığı vardır ve B ile C köşelerinden yan kenarlara indirilen yükseklikler K noktasında kesişmektedir. m(BKC) = 130° olduğuna göre tepe açısı m(BAC) kaç derecedir?', '50°', ['40 derece', '65 derece', '80 derece'], 'K noktası dar açılı ABC üçgeninin diklik merkezidir. Diklik merkezinde m(BAC) + m(BKC) = 180° olduğundan m(BAC) = 180° - 130° = 50° bulunur.'),
  ('Dik kenar uzunlukları 15 cm ve 20 cm olan bir dik üçgende hipotenüse ait kenarortay uzunluğu (V) ile hipotenüse ait yükseklik uzunluğu (h) arasındaki V - h farkı kaç santimetredir?', '0,5 cm', ['1 santimetre', '1,5 santimetre', '2 santimetre'], '15-20-25 dik üçgeninde hipotenüs 25 cm olduğundan muhteşem üçlüden V = 25 / 2 = 12,5 cm ve Öklid alan bağıntısından h = (15 · 20) / 25 = 12 cm olur; farkları 12,5 - 12 = 0,5 cm\'dir.'),
  ('Bir üçgende bir dış açının ölçüsü 112° ve bu dış açıya komşu olmayan iki iç açıdan birinin ölçüsü diğerinin 3 katıdır. Büyük olan bu iç açı kaç derecedir?', '84°', ['68 derece', '76 derece', '88 derece'], 'Bir dış açı kendisine komşu olmayan iki iç açının toplamına eşittir: k + 3k = 4k = 112° => k = 28° ve büyük olan açı 3 · 28° = 84° bulunur.'),
  ('ABC üçgeninde [AB] kenarı üzerinde D, [BC] kenarı üzerinde E noktası alınıyor ve |BD| = |BE| ikizkenarlığı veriliyor. m(BAC) = 52° ve m(ACB) = 38° olduğuna göre m(BDE) açısı kaç derecedir?', '45°', ['40 derece', '50 derece', '55 derece'], 'ABC üçgeninde m(ABC) = 180° - (52° + 38°) = 90° bulunur. BDE ikizkenar dik üçgen olduğundan m(BDE) = (180° - 90°) / 2 = 45° olur.'),
  ('Üçgen şeklindeki düzlemsel bir metal levha, tek bir destek çubuğunun sivri ucu üzerine yatay biçimde yerleştirildiğinde devrilmeden dengede kalmaktadır. Homojen kalınlıktaki bu levhada destek ucunun değdiği nokta aşağıdakilerden hangisidir?', 'Kenarortayların kesişim noktası', ['Yüksekliklerin kesişim noktası', 'İç açıortayların kesişim noktası', 'Kenar orta dikmelerin kesişimi'], 'Düzgün ve homojen üçgensel bir levhanın kütle (denge) merkezi, üç kenarortayın kesişim noktası olan ağırlık merkezidir.'),
  ('Üç doğrusal karayolunun sınırladığı üçgen biçimindeki bir sanayi bölgesinin içine, her üç karayoluna da eşit en kısa mesafede bulunacak bir itfaiye istasyonu kurulacaktır. İstasyonun konumu üçgenin hangi noktasında seçilmelidir?', 'İç açıortayların kesişim noktasında', ['Kenar orta dikmelerin kesiminde', 'Kenarortayların kesişim noktasında', 'Yükseklik doğrularının kesiminde'], 'Bir noktanın doğrulara en kısa mesafesi dik uzaklığıdır; üç kenara da eşit dik uzaklıkta bulunan iç nokta, iç açıortayların kesim noktası (iç teğet çember merkezi) olur.'),
  ('Aralarında doğrusal olmayan (üçgen oluşturan) üç baz istasyonunun her birine eşit kuş uçuşu uzaklıkta bulunan bir kontrol kulübesi inşa edilecektir. Kulübenin yeri bu üçgenin hangi yardımcı elemanlarının kesişim noktasındadır?', 'Kenar orta dikme doğrularının', ['İç açıortay doğru parçalarının', 'Kenarortay doğru parçalarının', 'Yükseklik doğru parçalarının'], 'Üçgenin üç köşesine eşit uzaklıkta bulunan nokta çevrel çemberin merkezidir ve kenar orta dikme doğrularının kesişimiyle bulunur.'),
  ('Eşkenar üçgen biçimindeki bir kağıdın bir kenar uzunluğu 12 cm\'dir. Üç köşesinden birer kenarı 2 cm olan eşkenar üçgenler kesilip çıkarıldığında geriye kalan düzgün olmayan altıgenin alanı kaç santimetrekaredir?', '33√3 cm²', ['30√3 santimetrekare', '32√3 santimetrekare', '34√3 santimetrekare'], 'Büyük eşkenar üçgenin alanı 12²√3 / 4 = 36√3 cm²\'dir. Köşelerden kesilen üç küçük eşkenar üçgenin her birinin alanı 2²√3 / 4 = √3 cm² olup üçünün toplamı 3√3 cm²\'dir; kalan alan 36√3 - 3√3 = 33√3 cm² olur.'),
  ('ABC üçgeninde [DE] orta tabandır (D ∈ [AB], E ∈ [AC]). [DC] ve [BE] kenarortayları G noktasında kesişmektedir. Çevre(GDE) = 14 cm olduğuna göre Çevre(GBC) kaç santimetredir?', '28 cm', ['21 santimetre', '35 santimetre', '42 santimetre'], '[DE] // [BC] ve |DE| / |BC| = 1 / 2 olduğundan kelebek benzerliğinden GDE ~ GCB benzerlik oranı 1 / 2 olur; dolayısıyla Çevre(GBC) = 2 · 14 = 28 cm bulunur.'),
  ('ABC üçgeninde [AD] açıortay (D ∈ [BC]), [DE] ⊥ [AB] ve |DE| = 5 cm\'dir. |AC| = 14 cm olduğuna göre ADC üçgeninin alanı kaç santimetrekaredir?', '35 cm²', ['28 santimetrekare', '42 santimetrekare', '70 santimetrekare'], 'Açıortay üzerindeki D noktasından açının kollarına ([AB] ve [AC]) indirilen dikmelerin uzunlukları birbirine eşittir; dolayısıyla D\'den [AC]\'ye inen yükseklik de 5 cm\'dir ve Alan(ADC) = (14 · 5) / 2 = 35 cm² olur.'),
  ('Bir üçgende üç kenar uzunluğunun aritmetik ortalaması 12 cm ve iç teğet çemberinin yarıçapı 3,5 cm olduğuna göre bu üçgenin alanı kaç santimetrekaredir?', '63 cm²', ['42 santimetrekare', '54 santimetrekare', '84 santimetrekare'], 'Üç kenarın aritmetik ortalaması 12 cm ise çevre 3 · 12 = 36 cm ve yarı çevre u = 18 cm\'dir. Alan = u · r = 18 · 3,5 = 63 cm² bulunur.'),
];
